fn main(){let root="target/qualification/";let suffix="/source/target/qualification/native-arithmetic-generation/arithmetic_counter_subtract/counter.litematic";let a=reda::formats::litematic::load(std::path::Path::new(&format!("{root}sequential-efficiency-baseline{suffix}"))).unwrap();let b=reda::formats::litematic::load(std::path::Path::new(&format!("{root}sequential-efficiency-obstruction-bounds{suffix}"))).unwrap();assert_eq!(a.size(),b.size());assert_eq!(a.cells().len(),b.cells().len());for (&x,&y) in a.cells().iter().zip(b.cells()){assert_eq!(a.palette().get(x),b.palette().get(y));}println!("Every loaded cell and complete block state equal; palette-index encoding may differ. Cells checked: {}",a.cells().len());}
